/// One user change to the personal ledger: `LedgerChange`, `(ledger) => ledger`.
///
/// A change is a pure function applied to the *latest* ledger, never a stored result: the
/// caller applies it to its current local snapshot, then materializes due occurrences
/// (`Recurrence.materialize`), and the same change can be re-applied after a sync brings a
/// newer snapshot. It never mutates its input; a refused change throws and returns nothing,
/// so there is no partial write. Ids are generated by the caller, once, before building it.
///
/// "Stale" checks compare the record the form was opened with (`original`) to the record in
/// the ledger now. Any difference means another device changed it, and the change is refused
/// so the person reviews the latest version instead of overwriting it.
public struct LedgerChange: Sendable {
    private let body: @Sendable (Ledger) throws(LedgerRuleError) -> Ledger

    public init(_ body: @escaping @Sendable (Ledger) throws(LedgerRuleError) -> Ledger) {
        self.body = body
    }

    public func apply(to ledger: Ledger) throws(LedgerRuleError) -> Ledger { try body(ledger) }
}

extension LedgerChange {
    /// Adds or replaces an entry (matched by id; the saved entry moves to the end), and adds
    /// `rule` when the entry starts a schedule. `original` is the entry as the form opened it;
    /// nil for a new entry.
    public static func saveEntry(
        _ entry: LedgerEntry, original: LedgerEntry? = nil, rule: RecurringRule? = nil
    ) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            try requireAccount(entry.accountId, in: ledger)
            if let rule { try requireAccount(rule.accountId, in: ledger) }
            if let tripId = entry.tripId, entry.kind != .expense || ledger.trip(id: tripId) == nil {
                throw .tripUnavailable
            }
            guard ledger.categories.contains(where: { $0.id == entry.categoryId && $0.kind == entry.kind }) else {
                throw .categoryRemoved
            }
            if let original, ledger.entry(id: original.id) != original { throw .entryChangedOnAnotherDevice }
            var next = ledger
            next.transactions.removeAll { $0.id == entry.id }
            next.transactions.append(entry)
            if let rule { next.recurring.append(rule) }
            return next
        }
    }

    /// Deletes an entry. Deleting a recorded occurrence never brings it back: its rule's
    /// `nextDate` is already past it.
    public static func deleteEntry(_ original: LedgerEntry) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            guard ledger.entry(id: original.id) == original else { throw .entryChangedBeforeDelete }
            var next = ledger
            next.transactions.removeAll { $0.id == original.id }
            return next
        }
    }

    /// Replaces a rule. Its recorded occurrences keep their own values: editing a schedule
    /// changes future occurrences only.
    public static func saveSchedule(_ rule: RecurringRule, original: RecurringRule) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            try requireAccount(rule.accountId, in: ledger)
            guard ledger.rule(id: original.id) == original else { throw .scheduleChangedOnAnotherDevice }
            guard ledger.categories.contains(where: { $0.id == rule.categoryId && $0.kind == rule.kind }) else {
                throw .categoryRemoved
            }
            var next = ledger
            next.recurring = ledger.recurring.map { $0.id == original.id ? rule : $0 }
            return next
        }
    }

    /// Pauses or resumes a rule. Resuming skips every date on or before `today`, so a pause
    /// never records the dates it covered. Pausing, or resuming an active rule, keeps
    /// `nextDate`. An unknown id changes nothing.
    public static func setScheduleActive(id: String, active: Bool, today: CalendarDate) -> LedgerChange {
        LedgerChange { ledger in
            var next = ledger
            next.recurring = ledger.recurring.map { rule in
                guard rule.id == id else { return rule }
                var rule = rule
                if active, !rule.active {
                    while rule.nextDate <= today {
                        rule.nextDate = Recurrence.next(
                            after: rule.nextDate, frequency: rule.frequency, anchorDay: rule.anchorDay)
                    }
                }
                rule.active = active
                return rule
            }
            return next
        }
    }

    /// Removes a rule and keeps its history: recorded occurrences keep their `recurringId`.
    public static func removeSchedule(id: String) -> LedgerChange {
        LedgerChange { ledger in
            var next = ledger
            next.recurring.removeAll { $0.id == id }
            return next
        }
    }

    /// Adds, edits (`original` set) or removes a trip. The name is trimmed with JavaScript's
    /// whitespace rules and must be 1...80 UTF-16 code units and unique ignoring case.
    public static func saveTrip(_ trip: Trip, original: Trip? = nil, remove: Bool = false) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            if let original, ledger.trip(id: original.id) != original { throw .tripChangedOnAnotherDevice }
            if remove, ledger.transactions.contains(where: { $0.tripId == trip.id }) { throw .tripHasEntries }
            var trip = trip
            trip.name = JavaScriptText.trim(trip.name)
            var next = ledger
            if remove {
                next.trips.removeAll { $0.id == trip.id }
                return next
            }
            guard (1...80).contains(JavaScriptText.length(trip.name)) else { throw .invalidTripName }
            guard trip.startDate.isWithinLedgerRange, trip.endDate.isWithinLedgerRange, trip.endDate >= trip.startDate
            else { throw .invalidTripDates }
            if ledger.trips.contains(where: { $0.id != trip.id && sameName($0.name, trip.name) }) {
                throw .duplicateTripName
            }
            if original == nil, ledger.trips.count >= Ledger.maxTrips { throw .tooManyTrips }
            if original != nil {
                next.trips = ledger.trips.map { $0.id == trip.id ? trip : $0 }
            } else {
                next.trips.append(trip)
            }
            return next
        }
    }

    /// Adds, edits or removes a payment account. The name rules match trips, with 50 units.
    public static func saveAccount(
        _ account: PaymentAccount, original: PaymentAccount? = nil, remove: Bool = false
    ) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            if let original, ledger.account(id: original.id) != original { throw .accountChangedOnAnotherDevice }
            if remove,
                ledger.transactions.contains(where: { $0.accountId == account.id })
                    || ledger.recurring.contains(where: { $0.accountId == account.id })
            {
                throw .accountHasEntries
            }
            var account = account
            account.name = JavaScriptText.trim(account.name)
            var next = ledger
            if remove {
                next.accounts.removeAll { $0.id == account.id }
                return next
            }
            guard (1...50).contains(JavaScriptText.length(account.name)) else { throw .invalidAccountName }
            if ledger.accounts.contains(where: { $0.id != account.id && sameName($0.name, account.name) }) {
                throw .duplicateAccountName
            }
            if original == nil, ledger.accounts.count >= Ledger.maxAccounts { throw .tooManyAccounts }
            if original != nil {
                next.accounts = ledger.accounts.map { $0.id == account.id ? account : $0 }
            } else {
                next.accounts.append(account)
            }
            return next
        }
    }

    /// Adds, edits or removes a category. A category in use by an entry or rule cannot be
    /// removed, or change kind (every entry must use a category of its own kind). Names are
    /// unique ignoring case within a kind.
    public static func saveCategory(
        _ category: LedgerCategory, original: LedgerCategory? = nil, remove: Bool = false
    ) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            if let original, ledger.category(id: original.id) != original { throw .categoryChangedOnAnotherDevice }
            let inUse =
                ledger.transactions.contains { $0.categoryId == category.id }
                || ledger.recurring.contains { $0.categoryId == category.id }
            if remove, inUse { throw .categoryHasEntries }
            var category = category
            category.name = JavaScriptText.trim(category.name)
            var next = ledger
            if remove {
                next.categories.removeAll { $0.id == category.id }
                return next
            }
            guard (1...50).contains(JavaScriptText.length(category.name)) else { throw .invalidCategoryName }
            if ledger.categories.contains(where: {
                $0.id != category.id && $0.kind == category.kind && sameName($0.name, category.name)
            }) {
                throw .duplicateCategoryName
            }
            if inUse, let current = ledger.category(id: category.id), current.kind != category.kind {
                throw .categoryKindInUse
            }
            if original == nil, ledger.categories.count >= Ledger.maxCategories { throw .tooManyCategories }
            if original != nil {
                next.categories = ledger.categories.map { $0.id == category.id ? category : $0 }
            } else {
                next.categories.append(category)
            }
            return next
        }
    }

    /// Changes the ledger currency, only while the ledger has no entries and no rules.
    public static func changeCurrency(_ currency: Currency) -> LedgerChange {
        LedgerChange { (ledger) throws(LedgerRuleError) in
            guard ledger.transactions.isEmpty, ledger.recurring.isEmpty else { throw .currencyLocked }
            var next = ledger
            next.currency = currency
            return next
        }
    }

    private static func requireAccount(_ accountId: String?, in ledger: Ledger) throws(LedgerRuleError) {
        if let accountId, ledger.account(id: accountId) == nil { throw .accountRemoved }
    }

    /// The duplicate-name test: `a.toLowerCase() === b.toLowerCase()`, compared by
    /// UTF-16 code units like `===` (Swift's `==` would also equate canonically equivalent text).
    private static func sameName(_ lhs: String, _ rhs: String) -> Bool {
        JavaScriptText.lowercase(lhs).utf16.elementsEqual(JavaScriptText.lowercase(rhs).utf16)
    }
}
